public class Logger {
    private final Map<String, Integer> lastTime = new HashMap<>();
    private static final int INTERVAL = 10;

    public boolean shouldPrintMessage(int timestamp, String message) {
        Integer last = lastTime.get(message);
        if (last == null || timestamp - last >= INTERVAL) {
            lastTime.put(message, timestamp);
            return true;
        }
        return false;
    }
}

