private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int pos=i;
    while (pos < bb.limit()){
        int b1 = bb.get(pos) & 0xFF;
        int cp;
        int bytesNeeded;
        if ((b1 & 0x80)==0){
            cp=b1;
            bytesNeeded=1;
        }else if ((b1 & 0xE0)==0xC0){
            cp=b1 & 0x1F;
            bytesNeeded=2;
        }else if ((b1 & 0xF0)==0xE0){
            cp=b1 & 0x0F;
            bytesNeeded=3;
        }else if ((b1 & 0xF8)==0xF0){
            cp=b1 & 0x07;
            bytesNeeded=4;
        }else{
            // invalid
            cp=0xFFFD;
            bytesNeeded=1;
        }
        if (pos+bytesNeeded > bb.limit()){
            break; // incomplete
        }
        for (int k=1;k<bytesNeeded;k++){
            int b = bb.get(pos+k) & 0x3F;
            cp = (cp << 6) | b;
        }
        sb.append(Character.toChars(cp));
        pos += bytesNeeded;
    }
    return pos;
}

