import java.util.*;

public class SymbolTable {
    private final List<TypeSymbol> typeTable = new ArrayList<>();
    private final Map<String, Integer> indexMap = new HashMap<>();

    public int addType(final String value) {
        Integer existing = indexMap.get(value);
        if (existing != null) {
            return existing;
        }
        int idx = typeTable.size();
        typeTable.add(new TypeSymbol(value));
        indexMap.put(value, idx);
        return idx;
    }

