public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String rawPath = u.getRawPath(); // percent-encoded path
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Remove leading slash if absolute and not considered delimiter
    if (rawPath.startsWith("/") && !decode) {
        // but even when decode, leading slash is ignored
        rawPath = rawPath.substring(1);
    } else if (rawPath.startsWith("/") && decode) {
        rawPath = rawPath.substring(1);
    }
    // Split by '/'
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String segment = decode ? urlDecode(part) : part;
        segments.add(new PathSegmentImpl(segment, part));
    }
    return segments;
}

