class ByteVector {
    private byte[] buffer;
    private int pos;

    public ByteVector() {
        this.buffer = new byte[32];
        this.pos = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength < 0) throw new IllegalArgumentException("Negative byteLength");
        ensureCapacity(pos + byteLength);
        if (byteArrayValue != null) {
            System.arraycopy(byteArrayValue, byteOffset, buffer, pos, byteLength);
        } else {
            for (int i = 0; i < byteLength; i++) {
                buffer[pos + i] = 0;
            }
        }
        pos += byteLength;
        return this;
    }

    private void ensureCapacity(int minCapacity) {
        if (minCapacity > buffer.length) {
            int newCap = Math.max(buffer.length * 2, minCapacity);
            byte[] newBuf = new byte[newCap];
            System.arraycopy(buffer, 0, newBuf, 0, pos);
            buffer = newBuf;
        }
    }
}

