private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || vertices.isEmpty()) {
        return true;
    }
    for (V v : vertices) {
        for (V w : vertices) {
            if (v.equals(w)) {
                continue;
            }
            if (!graph.containsEdge(v, w) && !graph.containsEdge(w, v)) {
                return false;
            }
        }
    }
    return true;
}

